import fs from "node:fs";
import path from "node:path";
import postgres from "postgres";
import { encode } from "@auth/core/jwt";

/**
 * E2E global setup — creates a disposable authenticated state for the isolated test environment.
 *
 * Safety contract:
 * - Runs ONLY against a localhost DATABASE_URL (refused otherwise).
 * - Signs the session with the throwaway E2E_AUTH_SECRET generated by scripts/run-e2e.cjs —
 *   never the real AUTH_SECRET.
 * - The emitted storage state lives in playwright/.auth/ (gitignored). It must never be committed.
 * - The e2e user's rows are recreated from scratch on every run so tests see a brand-new learner.
 */
const E2E_EMAIL = "e2e-test@example.com";
const E2E_NAME = "E2E Test User";

export default async function globalSetup() {
  const secret = process.env.E2E_AUTH_SECRET;
  const url = process.env.DATABASE_URL;
  if (!secret) throw new Error("E2E_AUTH_SECRET missing — run e2e via `npm run test:e2e`");
  if (!url) throw new Error("DATABASE_URL missing for e2e global setup");
  if (!/localhost|127\.0\.0\.1/.test(url)) {
    throw new Error("e2e global setup refuses to run against a non-localhost database");
  }

  const sql = postgres(url, { connect_timeout: 10, prepare: false });
  try {
    // Reset: FK cascades clean every user-scoped table for the disposable account.
    await sql`DELETE FROM users WHERE email = ${E2E_EMAIL}`;
    const inserted = await sql`
      INSERT INTO users (email, name) VALUES (${E2E_EMAIL}, ${E2E_NAME}) RETURNING id
    `;
    const userId = (inserted[0] as { id: string }).id;

    const maxAge = 30 * 24 * 60 * 60;
    const now = Math.floor(Date.now() / 1000);
    const jwt = await encode({
      token: {
        name: E2E_NAME,
        email: E2E_EMAIL,
        sub: userId,
        userId,
        picture: null,
        iat: now,
        exp: now + maxAge,
      },
      secret,
      salt: "authjs.session-token",
    });

    const stateDir = path.join("playwright", ".auth");
    fs.mkdirSync(stateDir, { recursive: true });
    fs.writeFileSync(
      path.join(stateDir, "state.json"),
      JSON.stringify({
        cookies: [
          {
            name: "authjs.session-token",
            value: jwt,
            domain: "localhost",
            path: "/",
            httpOnly: true,
            secure: false,
            sameSite: "Lax" as const,
            expires: now + maxAge,
          },
        ],
        origins: [],
      })
    );
    console.log(`e2e auth state written for disposable user ${userId} (localhost only)`);
  } finally {
    await sql.end({ timeout: 5 }).catch(() => {});
  }
}
